mapper.select:

where del_flag = '0'

    and portal_code = #{portalCode}


    and section_code = #{sectionCode}


    and category_code = #{categoryCode}


    and title like concat('%', #{title}, '%')


    and status = #{status}

order by sort_order asc, content_id desc


where del_flag = '0'
  and status = '0'
  and portal_code = #{portalCode}

    and section_code = #{sectionCode}


    and category_code = #{categoryCode}


    and (
        title like concat('%', #{keyword}, '%')
        or summary like concat('%', #{keyword}, '%')
        or source_name like concat('%', #{keyword}, '%')
    )

order by sort_order asc, publish_time desc, content_id desc

    limit #{limit}
